def bfs(start,targets):
    from collections import deque
    q=deque([start]);prev={start:None};mv={}
    dirs=[(-5,0,'U'),(5,0,'D'),(0,-5,'L'),(0,5,'R')]
    while q:
        y,x=q.popleft()
        if (y,x) in targets:
            p=[];c=(y,x)
            while prev[c] is not None:p.append(mv[c]);c=prev[c]
            return (y,x),''.join(reversed(p))
        for dy,dx,a in dirs:
            ny,nx=y+dy,x+dx
            if (ny,nx) not in prev and free(ny,nx):
                prev[(ny,nx)]=(y,x);mv[(ny,nx)]=a;q.append((ny,nx))
    return None,None
